input.command:
cd "$PWD" && python -c "
import databricks.sdk
w = databricks.sdk.WorkspaceClient()
print('--- spark versions (LTS) ---')
try:
    for v in w.clusters.spark_versions().versions:
        if 'LTS' in v.name and 'ML' in v.name:
            print(' ', v.key, '|', v.name)
except Exception as e:
    print('err', e)
print('--- node types (smallest few) ---')
try:
    nts = w.clusters.list_node_types().node_types
    nts = sorted([n for n in nts if n.num_cores and n.memory_mb], key=lambda n:(n.num_cores, n.memory_mb))[:6]
    for n in nts:
        print(' ', n.node_type_id, n.num_cores, n.memory_mb)
except Exception as e:
    print('err', e)
"
